"""mpl_toolkits.axisartist.angle_helper — angle utilities."""

import numpy as _np

class LocatorBase:
    """Base for angle-axis tick locators. Stores ``den`` (denominator
    for fractional steps) and ``include_last``."""

    def __init__(self, den=4, include_last=True):
        self.den = int(den)
        self.include_last = bool(include_last)


class LocatorDMS(LocatorBase):
    """Tick locator for degrees-minutes-seconds axes — picks a step
    that's a whole number of arc-seconds, arc-minutes, or degrees."""

    def __call__(self, v1, v2):
        span = abs(v2 - v1) * 3600  # arc-seconds
        candidates = [1, 5, 10, 15, 30, 60, 300, 600, 900, 1800, 3600,
                       7200, 18000, 36000, 108000]
        step_sec = next((c for c in candidates
                         if span / c <= max(self.den, 1)), 36000)
        step_deg = step_sec / 3600.0
        vals = []
        v = (int(v1 / step_deg) - 1) * step_deg
        while v <= v2 + step_deg * 0.5:
            if v1 - step_deg * 1e-6 <= v <= v2 + step_deg * 1e-6:
                vals.append(v)
            v += step_deg
        if not self.include_last and vals and vals[-1] > v2:
            vals = vals[:-1]
        return vals, len(vals), 1.0


class LocatorHMS(LocatorBase):
    """Tick locator for hours-minutes-seconds time axes."""

    def __call__(self, v1, v2):
        span = abs(v2 - v1) * 3600
        candidates = [1, 5, 10, 15, 30, 60, 300, 600, 1800, 3600,
                       7200, 18000, 36000]
        step_sec = next((c for c in candidates
                         if span / c <= max(self.den, 1)), 3600)
        step_h = step_sec / 3600.0
        vals = []
        v = (int(v1 / step_h) - 1) * step_h
        while v <= v2 + step_h * 0.5:
            if v1 - step_h * 1e-6 <= v <= v2 + step_h * 1e-6:
                vals.append(v)
            v += step_h
        if not self.include_last and vals and vals[-1] > v2:
            vals = vals[:-1]
        return vals, len(vals), 1.0


class LocatorD(LocatorBase):
    """N evenly-spaced tick locator in degrees."""

    def __init__(self, nbins=8, include_last=True):
        super().__init__(den=nbins, include_last=include_last)
        self.nbins = int(nbins)

    def __call__(self, v1, v2):
        span = v2 - v1
        step = select_step_degree(span / max(self.nbins - 1, 1)) if span else 1.0
        vals = []
        v = (int(v1 / step)) * step if step else v1
        while v <= v2 + step * 0.5:
            if v1 - step * 1e-6 <= v <= v2 + step * 1e-6:
                vals.append(v)
            v += step
        if not self.include_last and vals and vals[-1] > v2:
            vals = vals[:-1]
        return vals, len(vals), 1.0


class LocatorH(LocatorBase):
    """N evenly-spaced tick locator in hours."""

    def __init__(self, nbins=8, include_last=True):
        super().__init__(den=nbins, include_last=include_last)
        self.nbins = int(nbins)

    def __call__(self, v1, v2):
        return LocatorD(self.nbins, self.include_last)(v1, v2)


class FormatterDMS:
    """Format angle values as degrees(°), minutes(′), seconds(″)."""

    def __call__(self, direction, factor, values):
        out = []
        for v in values:
            deg_total = v * factor
            d = int(deg_total)
            m_total = abs(deg_total - d) * 60
            m = int(m_total)
            s = (m_total - m) * 60
            if m == 0 and abs(s) < 1e-6:
                out.append(f'{d}°')
            elif abs(s) < 1e-6:
                out.append(f'{d}°{m:02d}′')
            else:
                out.append(f'{d}°{m:02d}′{s:05.2f}″')
        return out


class FormatterHMS:
    """Format time values as hours(h), minutes(m), seconds(s)."""

    def __call__(self, direction, factor, values):
        out = []
        for v in values:
            h_total = v * factor
            h = int(h_total)
            m_total = abs(h_total - h) * 60
            m = int(m_total)
            s = (m_total - m) * 60
            if m == 0 and abs(s) < 1e-6:
                out.append(f'{h}h')
            elif abs(s) < 1e-6:
                out.append(f'{h}h{m:02d}m')
            else:
                out.append(f'{h}h{m:02d}m{s:05.2f}s')
        return out


def select_step_degree(dv):
    """Pick a "nice" degree step >= ``dv``. Chooses from the canonical
    1/2/2.5/5/10/15/30/45/90 ladder after rescaling by the closest power
    of 10. Used by LocatorD's tick algorithm."""
    import math as _m
    if dv <= 0:
        return 1.0
    mag = 10 ** _m.floor(_m.log10(dv))
    normalized = dv / mag
    for s in (1.0, 2.0, 2.5, 5.0, 10.0):
        if s >= normalized:
            return float(s * mag)
    return float(10 * mag)


def select_step_hour(dv):
    """Pick a tick step in hours — same algorithm as degrees but a
    different "nice" ladder."""
    import math as _m
    if dv <= 0:
        return 1.0
    for s in (1, 2, 3, 4, 6, 12, 24):
        if s >= dv:
            return float(s)
    return float(24 * _m.ceil(dv / 24))


def select_step_sub(dv):
    """Pick a sub-degree (arcminute / arcsecond) step <= ``dv``."""
    if dv <= 0:
        return 1.0
    for s in (1/3600, 1/600, 1/60, 1/30, 1/12, 1/6, 1/4, 1/2, 1.0):
        if s >= dv:
            return s
    return 1.0


def select_step(dv, factor, is_hour=False):
    """Top-level "pick a nice step" entry point. Returns ``(step,
    nticks, factor)`` matching upstream's signature so the caller can
    feed it straight into a Locator."""
    step = select_step_hour(dv) if is_hour else select_step_degree(dv)
    nticks = max(1, int(abs(dv) / step) + 1) if step else 1
    return step, nticks, factor


