class ExtremeFinderCycle:
    """Find the parameter extremes for a cyclic axis (degrees of arc)."""

    def __init__(self, nx=20, ny=20, lon_cycle=360, lat_cycle=None,
                 lon_minmax=None, lat_minmax=None):
        self.nx = nx
        self.ny = ny
        self.lon_cycle = lon_cycle
        self.lat_cycle = lat_cycle
        self.lon_minmax = lon_minmax
        self.lat_minmax = lat_minmax

    def __call__(self, transform_xy, x1, y1, x2, y2):
        # Return the four corner pairs as the extremes.
        return (min(x1, x2), max(x1, x2), min(y1, y2), max(y1, y2))


class LocatorDM:
    """Locator for degrees/minutes labelling — picks tick positions in
    DM format."""

    def __init__(self, nbins=10):
        self.nbins = nbins

    def __call__(self, vmin, vmax):
        step = (vmax - vmin) / max(1, self.nbins)
        out, v = [], vmin
        while v <= vmax + 1e-9:
            out.append(v)
            v += step
        return out, len(out), 1.0


class LocatorHM(LocatorDM):
    """Locator for hours/minutes labelling — picks tick positions in
    HM format. Inherits LocatorDM's grid logic."""
    pass


def select_step24(v1, v2, *, hour=False):
    """Pick a nice tick step for an interval ``[v1, v2]`` that's a
    multiple of 24 (or another multiple of 12 / 6 / 3 / 1) — used
    for hour-style ticks."""
    span = abs(v2 - v1)
    for step in (24, 12, 6, 3, 1):
        if span / step >= 4:
            return step, len([0]), step
    return 1, 1, 1.0


def select_step360(v1, v2, num):
    """Pick a nice tick step for a 0-360° cyclic interval. Returns
    ``(step, nticks, factor)``."""
    span = abs(v2 - v1)
    for step in (45, 30, 15, 10, 5, 1):
        if span / step >= num // 2:
            return step, max(1, int(span / step)), step
    return 1, max(1, int(span)), 1.0
